const input = JSON.parse(source || "{}");

const headers = { "content-type": "application/json" };
const { transferId, idempotencyKey, fromId, toId, amount } = input;
const fromVersion = input.fromVersion;
const toVersion = input.toVersion;

function out(status, body, o = {}) {
  const accounts = o.accounts ?? [
    { id: fromId, balance: input.fromBalance, version: fromVersion },
    { id: toId, balance: input.toBalance, version: toVersion }
  ];
  return {
    http: { status, headers, body },
    database: { accounts, transaction: { committed: !!o.committed, ...(o.committed ? {} : { rolledBack: !!o.rolledBack }) } },
    messages: o.messages ?? [],
    ordering: o.ordering ?? [],
    failures: o.failures ?? [],
    retryability: !!o.retryable
  };
}

function run() {
  const seen = input.existingTransfer ?? input.replay ?? input.previousResult;
  const replayed = (seen && typeof seen === "object") || input.replayed === true || input.idempotentReplay === true;
  if (replayed) {
    const prior = seen && typeof seen === "object" ? seen : {};
    return out(200, {
      transferId: prior.transferId ?? transferId,
      fromBalance: prior.fromBalance ?? input.fromBalance,
      toBalance: prior.toBalance ?? input.toBalance,
      replayed: true
    }, { committed: false });
  }

  const invalid = !Number.isFinite(amount) || amount <= 0 || !fromId || !toId || fromId === toId;
  if (invalid) {
    return out(400, { error: "invalid_request" }, { rolledBack: true, failures: ["invalid_request"] });
  }

  const expectedFrom = input.expectedFromVersion ?? fromVersion;
  const expectedTo = input.expectedToVersion ?? toVersion;
  const currentFrom = input.currentFromVersion ?? fromVersion;
  const currentTo = input.currentToVersion ?? toVersion;
  if (expectedFrom !== currentFrom || expectedTo !== currentTo) {
    return out(409, { error: "version_conflict" }, {
      rolledBack: true, failures: ["version_conflict"], retryable: true
    });
  }

  if (input.fromBalance < amount) {
    return out(422, { error: "insufficient_funds" }, {
      rolledBack: true, failures: ["insufficient_funds"]
    });
  }

  const fromBalance = input.fromBalance - amount;
  const toBalance = input.toBalance + amount;
  const nextFrom = fromVersion + 1;
  const nextTo = toVersion + 1;
  return out(201, {
    transferId, fromBalance, toBalance, fromVersion: nextFrom, toVersion: nextTo
  }, {
